<script setup lang="ts">
import {onMounted,ref} from 'vue';
import {ifxTableAddress,api,type Tank,type Configuration,type CapacityDocument} from './api';
const props=defineProps<{tankId:string;configurationRevision:number;calculationRevision:number;initialTab?:string}>();
const emit=defineEmits<{close:[]}>();
type Basis={configurationRevision:number;configurationSavedAtUtc:string;tank:Tank;channel:Configuration['channels'][number];historyIntervalSeconds:number;readingExpirySeconds:number;calculationRevision:number;calculationSavedAtUtc:string|null;metering:Tank['metering']|null;pressure1:Tank['pressure1']|null;pressure2:Tank['pressure2']|null;tables:{id:string;revision:number;number:string;name:string;kind:string;pointCount:number;referenceDensityKgM3:number}[];formula:string};
const basis=ref<Basis|null>(null),error=ref(''),tab=ref(props.initialTab||'calculation'),table=ref<CapacityDocument|null>(null),tableError=ref('');
const kinds:Record<string,string>={Main:'主罐容表',StaticPressure:'静压力修正表',Decimal:'小数表'};
const date=(s:string|null|undefined)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'—';
async function showTable(id:string,revision:number){tableError.value='';try{table.value=await api('/api/capacity-tables/'+id+'?revision='+revision)}catch(e){tableError.value=e instanceof Error?e.message:String(e)}}
onMounted(async()=>{try{basis.value=await api('/api/record-basis?'+new URLSearchParams({tankId:props.tankId,configurationRevision:String(props.configurationRevision),calculationRevision:String(props.calculationRevision)}))}catch(e){error.value=e instanceof Error?e.message:String(e)}});
</script>
<template><div class="modal-backdrop"><section class="modal wide-modal record-basis-dialog" role="dialog" aria-label="查看记录依据"><div class="modal-head"><div><h2>查看记录依据</h2><p>显示本条数据引用的原版本；修改当前配置不会改变此处记录。</p></div><button class="button" @click="emit('close')">关闭</button></div><div class="modal-body"><p v-if="error" role="alert" class="error-message">{{error}}</p><p v-else-if="!basis">正在读取原版本…</p><template v-if="basis"><div class="tabs"><button :class="{active:tab==='calculation'}" @click="tab='calculation'">计量依据 {{basis.calculationRevision}}</button><button :class="{active:tab==='configuration'}" @click="tab='configuration'">配置记录 {{basis.configurationRevision}}</button></div><template v-if="tab==='calculation'"><p class="help">计量依据建立时间：{{date(basis.calculationSavedAtUtc)}}</p><p>{{basis.formula}}</p><dl v-if="basis.metering" class="basis-facts"><div><dt>体积计算</dt><dd>{{basis.metering.enabled?'启用':'停用'}}</dd></div><div><dt>{{basis.metering.waterHeightMm==null?'人工水体积（旧配置）':'水位（人工输入）'}}</dt><dd>{{basis.metering.waterHeightMm==null?basis.metering.waterVolumeM3+' m³':basis.metering.waterHeightMm+' mm；水体积按当时基础罐容算法计算'}}</dd></div><div><dt>质量计算密度</dt><dd>{{basis.metering.densitySource==='Manual'?'人工工况密度 '+basis.metering.manualOperatingDensityKgM3+' kg/m³':'仪表当时实测密度'}}；有效数据才参与</dd></div><div><dt>20℃标准密度</dt><dd>{{basis.metering.standardDensity20KgM3??'未填写'}} kg/m³（独立资料，不代替实测密度）</dd></div></dl><p class="help">基础体积算法：{{basis.metering?.baseVolumeMethod==='MainPlusDecimal'?'主表下节点＋小数增量':'主表插值'}}；不足1mm：{{basis.metering?.fractionalMillimetreRule==='IntegerOnly'?'仅整数毫米':'相邻毫米线性插值'}}</p><h3>当时关联的罐容表版本</h3><div v-if="basis.tables.length" class="table-wrap"><table><thead><tr><th>表类型</th><th>表编号 / 名称</th><th>版本</th><th>数据组数</th><th>查看</th></tr></thead><tbody><tr v-for="t in basis.tables" :key="t.id"><td>{{kinds[t.kind]}}</td><td>{{t.number}} · {{t.name}}<small v-if="t.kind==='StaticPressure'">参考密度 {{t.referenceDensityKgM3}} kg/m³</small></td><td>V{{t.revision}}</td><td>{{t.pointCount}}</td><td><button class="text-button" @click="showTable(t.id,t.revision)">查看该版本</button></td></tr></tbody></table></div><p v-else class="help">没有关联罐容表版本。</p><p v-if="tableError" class="error-message">{{tableError}}</p><section v-if="table" class="basis-table-preview"><h3>{{table.number}} · V{{table.revision}} 数据预览</h3><p class="help">仅预览前20组，共{{(table.decimalRows?.length||0)+table.points.length}}组；这是保存的原表版本。</p><table v-if="table.kind==='Decimal'&&(table.decimalRows?.length||0)>0"><thead><tr><th>起始mm</th><th>结束mm</th><th>序号</th><th>厘米增量L</th><th>毫米增量L</th></tr></thead><tbody><tr v-for="(r,i) in table.decimalRows.slice(0,20)" :key="i"><td>{{r.startHeightMm}}</td><td>{{r.endHeightMm}}</td><td>{{r.number}}</td><td>{{r.centimetreLitres}}</td><td>{{r.millimetreLitres}}</td></tr></tbody></table><table v-else><thead><tr><th>高度（{{table.heightUnit==='Metre'?'m':table.heightUnit==='Centimetre'?'cm':'mm'}}）</th><th>{{table.kind==='Main'?'容积':'容积增量 / 修正量'}}（{{table.volumeUnit==='Litre'?'L':'m³'}}）</th></tr></thead><tbody><tr v-for="(p,i) in table.points.slice(0,20)" :key="i"><td>{{p.height}}</td><td>{{p.volume}}</td></tr></tbody></table></section></template><template v-else><p class="help">配置保存时间：{{date(basis.configurationSavedAtUtc)}}</p><dl class="basis-facts"><div><dt>储罐</dt><dd>{{basis.tank.code}} · {{basis.tank.name||'—'}}</dd></div><div><dt>介质 / 罐区</dt><dd>{{basis.tank.medium}} / {{basis.tank.zone}}</dd></div><div><dt>罐高</dt><dd>{{basis.tank.heightMm}} mm</dd></div><div><dt>通讯通道</dt><dd>{{basis.channel.name}}</dd></div><div><dt>接入协议</dt><dd>{{basis.channel.protocol==='IfxL25'?'IFX30000':basis.channel.protocol}}</dd></div><div><dt>{{basis.channel.protocol==='IfxL25'?'表地址':'仪表地址'}}</dt><dd>{{basis.channel.protocol==='IfxL25'?ifxTableAddress(basis.tank.address,basis.channel.unitId):basis.tank.address}}</dd></div><div><dt>历史保存间隔</dt><dd>{{basis.historyIntervalSeconds}} 秒</dd></div><div><dt>数据有效期</dt><dd>{{basis.readingExpirySeconds}} 秒</dd></div></dl><dl class="basis-facts"><div><dt>罐径 / 公称容量</dt><dd>{{basis.tank.diameterMm??'—'}} mm / {{basis.tank.nominalCapacityM3??'—'}} m³</dd></div><div><dt>温度方式 / 温度计点数</dt><dd>{{basis.tank.temperatureMode==='Ats'?'固定点温度计':basis.tank.temperatureMode==='Wireless'?'无线浮子':'无温度计'}} / {{basis.tank.atsPointCount}}</dd></div><div><dt>仪表位号 / 产品编号</dt><dd>{{basis.tank.instrumentTag||'—'}} / {{basis.tank.productNumber||'—'}}</dd></div><div><dt>设备批次</dt><dd>{{basis.tank.batch||'—'}}</dd></div></dl></template></template></div></section></div></template>

